from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent
R=ROOT/'reports';R.mkdir(exist_ok=True)
plan=json.loads((R/'model_scale_plan.json').read_text())
policy=json.loads((ROOT/'models/ensemble_foundation/postprocess.json').read_text())
cap=json.loads((R/'model_scale_capacity_candidates.json').read_text())
next_config=json.loads((ROOT/'configs/model_scale_next.json').read_text())
esc=html.escape
def table(head,rows):
    return '<div class="scroll"><table><tr>'+''.join('<th>'+esc(str(v))+'</th>' for v in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in r)+'</tr>' for r in rows)+'</table></div>'
def link(url,title):return '<a href="'+esc(url,quote=True)+'">'+esc(title)+'</a>'
def mb(n):return f'{n/1e6:,.1f} MB'
def gb(n):return f'{n/1e9:,.3f} GB'
parts=['''<header><small>2026-10-24 · SCALE / MODELS / ENSEMBLE</small><h1>규모보다 독립 원천과 검증</h1><p>현재 데이터의 실제 사용 범위, 확장 시 저장·메모리 예상과 SOTA 후보의 적용 조건.</p></header>''']
parts.append('<section><h2>현재 준비 상태와 GPU</h2><p>현재 v1 데이터와 9개 모델의 CPU 결과는 이미 구축되어 있어 동결된 후보의 추론에 새 GPU 학습이 필요하지 않습니다. 고품질 확장 v2는 추가 원천 확보·품질 감사·분리 및 재학습 준비가 끝난 후 동결해야 합니다. 그 준비의 계획 범위는 약 1–3시간이며, 다운로드 속도·품질 탈락·규정 확인에 따라 달라집니다. 완료 시간을 실측한 값은 아닙니다.</p><p><strong>초기 자원 권장: RTX 4090 24GB × 1, CPU 8코어 이상, RAM 64GB 권장, 여유 SSD 100GB 권장.</strong> 4090의 VRAM 24GB는 공식 사양입니다. 현재 foundation 문맥과 estimator batch=1을 기준으로 한 계획이며 CUDA 메모리·속도는 아직 실측하지 않았습니다. 첫 서버 실행에서 4k→8k→16k 문맥의 peak allocated/reserved와 동기화된 시간을 측정해야 합니다. '+link('https://www.nvidia.com/en-us/geforce/graphics-cards/40-series/rtx-4090/','NVIDIA 사양')+'</p><p>48GB나 80GB는 큰 문맥·동시 배치·gradient fine-tuning에서 24GB의 측정 예산을 넘을 때 검토합니다. 8GB의 원본 파일 크기 자체는 큰 VRAM을 요구하는 근거가 아닙니다.</p></section>')
source_rows=[]
for r in plan['current_synthetic_source_audit']:
    source_rows.append([r['split'],r['synthetic_examples'],r['unique_background_windows_sampled'],r['background_sensor_groups_sampled'],r['background_site_days_sampled'],r['unique_added_reference_clips_sampled'],r['reference_source_groups_sampled']])
parts.append('<section><h2>명목 합성 수와 원천 다양성</h2>'+table(['분할','합성 수','고유 배경 윈도우','배경 센서 그룹','배경 site-days','실제 추가 참조 clips','참조 source-groups'],source_rows)+'<p>16,000개 학습 합성에는 실제로 14,738개 배경 윈도우와 995개 참조 clip이 사용됐습니다. 하지만 참조의 그룹 수는 107개(HearMyShip 날짜 16개, VTUAD 그룹 91개)이며 이것도 독립적인 물리 선박 수를 보증하지 않습니다. 검증 3,000개의 추가 참조는 183개 clip이나 원천 그룹은 5개뿐입니다. 별도 관측소 평가의 배경 센서 연결 그룹도 1개이므로 3,000개를 3,000개 독립 원천처럼 취급할 수 없습니다.</p><p>샘플을 20만 개로 늘리면 제어 비율·위치·채널 응답의 학습 범위는 늘지만 새 해역·날짜·선박·장비가 생기는 것은 아닙니다. 현재 uniform 배경 추출을 유지한다는 수학적 가정 아래 20만 합성은 약 82,144개의 고유 배경을 한 번 이상 쓸 것으로 기대됩니다. 이는 독립성 측정이나 새 녹음 수가 아닙니다.</p></section>')
fr=[]
for r in plan['forecasts']:
    fr.append([f'{r["synthetic_examples"]:,}',gb(r['all_four_arrays_bytes']),gb(r['compressed_bytes_if_current_ratio_persists']),gb(r['tabm_1254_feature_CPU_bytes']),gb(r['cnn_channels_plus_weights_CPU_bytes']),mb(r['foundation_96_feature_CPU_bytes'])])
parts.append('<section><h2>확장 시 저장 공간과 CPU 메모리</h2>'+table(['샘플 수','입력+셀 정답+스칼라','압축 추정','TabM 특징 행렬','CNN 채널+weights','96개 foundation 특징'],fr)+'<p>샘플당 float32 15×25 입력 1,500바이트, 셀 정답 1,500바이트, share/presence 8바이트로 총 3,008바이트입니다. 압축 비율은 현재 파일에서 측정한 약 0.506을 적용한 예측입니다. 추가 원천의 엔트로피·결측 구조가 바뀌면 달라집니다. 표의 파생 특징은 주로 CPU 배열이며 모두 GPU에 동시에 올리는 양이 아닙니다. Foundation의 내부 attention·KV cache는 이 작은 96차원 입력 행렬보다 훨씬 많은 메모리를 사용합니다.</p><p>실제 연속 녹음을 10/50/100시간 추가하면 서로 겹치지 않는 15분 구간은 최대 40/200/400개입니다. 48kHz mono PCM16의 압축 전 음원은 시간당 345.6MB이며, 2초×25대역 float32 은행은 시간당 약 0.18MB입니다. 실제 raw 포맷·압축률·채널 수는 각 원천 메타데이터로 산정해야 합니다.</p></section>')
results=[]
for name,label in [('tabicl_cpu_context16000','TabICLv2'),('kumo_large_cpu_context4096','Kumo Large')]:
    d=json.loads((ROOT/'models'/name/'manifest.json').read_text())
    fit=d.get('fit_seconds',d.get('context_fit_seconds'))
    results.append([label,f'{d["parameters"]:,}',d['context_rows'],d['members'],f'{fit:.1f}s',f'{d["results"]["validation"]["seconds"]:.1f}s',f'{d["peak_CPU_resident_GiB"]:.2f} GiB',f'{d["results"]["validation"]["rmse"]:.5f}',f'{d["results"]["domain_holdout"]["rmse"]:.5f}'])
parts.append('<section><h2>실제 실행한 사전학습 모델</h2>'+table(['모델','파라미터','문맥 행','멤버','CPU fit','CPU 예측 3k','CPU peak RSS','검증 RMSE','별도 관측소 RMSE'],results)+'<p>모두 vendor의 사전학습 가중치를 고정하고 합성 학습 context만 읽습니다. fit은 데이터별 신경망 가중치를 SGD로 학습한 시간이 아니라 문맥·정규화·캐시 준비 시간입니다. 위 메모리는 macOS CPU 프로세스의 peak RSS이며 GPU VRAM 실측치가 아닙니다.</p><p>TabICLv2는 공식 BSD-3-Clause, Kumo는 OpenMDW-1.1 가중치를 고정 revision/SHA-256으로 확보했습니다. Kumo 발표자의 일반 표형 벤치마크 결과는 유력한 비교 근거지만 이 대회에서의 SOTA 증거는 아닙니다. '+link('https://github.com/soda-inria/tabicl','TabICLv2 공식 코드')+' · '+link('https://huggingface.co/nvidia/Kumo-Tabular','Kumo 모델 카드')+' · '+link('https://huggingface.co/blog/nvidia/kumo-tabular','Kumo 공식 발표')+'</p></section>')
parts.append('<section><h2>9개 구성의 고정 앙상블</h2>'+table(['모델','검증으로 선택한 비중'],[[esc(k),f'{float(w)*100:.3f}%'] for k,w in zip(policy['models'],policy['weights'])])+table(['분할','원시 앙상블 RMSE','보정 후 RMSE'],[[s,f'{r["ensemble_rmse"]:.6f}',f'{r["calibrated_rmse"]:.6f}'] for s,r in policy['results'].items()])+f'<p>별도 보정 집합의 교차 적합으로 선택한 보정식: clip({policy["affine"][0]:.6f} × 예측 {policy["affine"][1]:+.6f}, 0, 1). 모델 비중은 validation만 사용했고 domain으로 다시 고르지 않았습니다. 현재 calibration 교차 적합은 표본 parity 2분할이므로 원천 독립 crossfit은 아니라는 한계가 있습니다. v2는 원천 그룹 기반 보정을 우선합니다.</p><p>Foundation의 score_added_vessel은 share를 그대로 쓰는 단순 진단 proxy이며 별도로 보정된 존재 확률이 아닙니다. 공식 순위는 share RMSE를 사용합니다. Test와 기존 sealed NOAA OC02_02는 이 병합·최적화에서 읽지 않았습니다.</p><p>정책: <code>models/ensemble_foundation/postprocess.json</code>, 추론 매핑: <code>foundation_specs.json</code>, source/order SHA 기록: <code>candidate_merge_manifest.json</code>.</p></section>')
parts.append('<section><h2>과적합과 과소적합 제어</h2><ul><li>합성 수 대신 녹음·선박·날짜·관측소의 원천 단위를 분리합니다. 인접 기간은 purge 검증을 적용합니다.</li><li>기존 v1에서 gradient 학습한 가중치와 context/scaler/cache를 바뀐 v2 검증에 그대로 쓰지 않습니다. 현재 대회 데이터로 업데이트되지 않은 vendor 원본 사전학습 가중치는 재사용할 수 있습니다.</li><li>Foundation의 context 행에 같은 정답을 보여준 채 예측한 오차를 train error로 보고하지 않습니다. 별도의 training-source 합성 probe 또는 leave-one-out context로 봅니다.</li><li>학습량·용량별 곡선과 원천 그룹별 오차를 함께 봅니다. train과 validation이 둘 다 나쁘면 용량·특징·최적화를 검토하고, train만 좋아지는 경우에는 모델 확대를 중단합니다.</li><li>새 원천 평가가 나쁘면 단순 과적합뿐 아니라 합성 prior·시간 포락선·장비/해역 차이도 검토합니다. 검증 MSE가 낮아졌다고 실해양 일반화를 단정하지 않습니다.</li></ul></section>')
nt=next_config['future_neural_training']
parts.append(f'<section><h2>다음 학습의 고정 조건</h2><p><strong>앞으로의 신경망 gradient 학습과 명시적인 미세 조정은 최대 {nt["max_epochs"]} epoch, validation 개선이 없는 {nt["early_stopping_patience"]} epoch 후 중단, optimizer {esc(nt["optimizer"])}를 사용합니다.</strong> 독립 원천 validation의 share MSE로 최선 checkpoint를 복원합니다. 기존 제출 모델은 소형 신경망 8 epoch의 AdamW 학습 결과이며, 이번 조건이 소급 적용된 것으로 표시하지 않습니다. 최대 100 epoch는 수렴이나 데이터 충분성을 보장하는 수치가 아닙니다.</p><p>TabICL/Kumo의 현재 frozen ICL에는 epoch와 optimizer가 없습니다. 대회 학습 context를 읽어 전처리와 추론 캐시를 만드는 fit입니다. 사전학습 모델에 gradient 미세 조정을 추가하려면 Adam·검증·checkpoint·early stopping을 지원하는 별도 정식 trainer부터 준비해야 합니다. 계획 파일: <code>configs/model_scale_next.json</code>.</p></section>')
native_path=ROOT/'external/expansion_research/native_reference_final_summary.json'
if native_path.exists():
    native=json.loads(native_path.read_text())
    parts.append('<section><h2>새 실제 연속 15분 원천의 확보량</h2>'+table(['분할','실제 clip 수','관측소 수','날짜 수','실제 분량'],[[r['split'],r['clips'],r['stations'],r['days'],str(r['minutes'])+'분'] for r in native['counts']])+f'<p>새 양성 원천 {native["positive_native_clips"]}개는 총 {native["positive_native_minutes"]}분, {native["unique_positive_stations"]}개 관측소/배치와 {native["unique_positive_days"]}개 날짜입니다. 원천 범위 전송 {mb(native["network_range_bytes_including_initial_probes"])}, FLAC crop {mb(native["total_crop_bytes"])}를 실측했습니다. 이는 현재 v1 제출 모델에 이미 주입됐다는 뜻이 아닙니다. 별도 sealed holdout은 모델 평가 전 상태로 보관합니다.</p><p>Ship annotation은 선박 사건의 관측 근거이며 고립된 선박 에너지의 정답이 아닙니다. 기존 배경 위에 명시적으로 추가한 에너지 비율의 합성 정답만 정확히 알 수 있습니다. 같은 90분 학습 원천을 반복 증강해도 독립 관측소·날짜 수가 늘지는 않습니다. NoShip clip은 양성에서 격리했고 자연 상태의 선박 부재 정답으로 사용하지 않습니다. 압력 보정이 적용되지 않은 digital energy라는 한계도 유지합니다.</p></section>')
parts.append('<section><h2>더 큰 SOTA와 라이선스</h2><p>1B를 크기만으로 금지하거나 최적이라고 가정하지 않습니다. 현재 과제에 맞는 사전학습 표형 모델과 강한 작은 모델을 함께 비교하는 편이 우선입니다. Chinchilla의 언어모델 계산량 배분 결과를 1분/셀 토큰으로 환산해 최소 수천 년 음원이 필요하다고 하는 계산, 또는 1–3M가 최적이라고 하는 단정은 채택하지 않습니다.</p>'+table(['후보','현재 상태 / 출처'],[
['TabPFN-3.5','공식 코드는 Apache-2.0이나 가중치 조건은 별도 NC/gated. 현재 미사용. '+link('https://github.com/PriorLabs/TabPFN','공식 저장소')],
['EXAONE-Tabular','코드와 가중치 라이선스가 다름. 현재 미사용. '+link('https://github.com/LGAI-Research/EXAONE-Tabular','공식 저장소')],
['Google TabFM','별도 non-commercial 가중치. 현재 미사용. '+link('https://github.com/google-research/tabfm','공식 저장소')],
['Xiaomi-TabLDM','공식 README에 코드 Apache/NC 가중치 설명이 혼재하여 권위 있는 weights 약관 확인 필요. 현재 미사용. '+link('https://github.com/xiaomi-research/xiaomi-tabldm','공식 저장소')],
['LimiX-2','NC 라이선스 §5가 일부 비상업 대회를 명시 허용하므로 NC를 일괄 금지로 해석하면 안 됨. 금전 보상·competing-FM/출력 이용 등 정확한 조건을 더 확인해야 하며 현재 미사용. '+link('https://huggingface.co/stable-ai/LimiX-2/blob/main/LICENSE','실제 약관')]
])+'<p>해당 후보의 eligibility가 확인되기 전 가중치를 다운로드하거나 현재 앙상블에 넣지 않습니다. 상위 벤치마크의 모델명만 추가해 실행된 것으로 표시하지 않습니다.</p></section>')
style='body{font:16px/1.7 -apple-system,BlinkMacSystemFont,sans-serif;background:#f5f7f3;color:#17241d;margin:0}header,section{max-width:1200px;margin:24px auto;padding:30px;background:white;border:1px solid #dce5d6}h1{font-size:40px;margin:12px 0}h2{font-size:25px}small{color:#617b64}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #dae1d5}th{background:#edf2e8}.scroll{overflow:auto}a{color:#256243}code{font-size:13px}p{max-width:1100px}'
(R/'model_scale_plan.html').write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>규모·SOTA·GPU·앙상블 계획</title><style>'+style+'</style><body>'+''.join(parts)+'</body></html>')
print('Created reports/model_scale_plan.html')
